def has_pair_with_sum(arr, target):
    left, right = 0, len(arr) - 1
    while left < right:
        current_sum = arr[left] + arr[right]
        if current_sum == target:
            return True
        elif current_sum < target:
            left += 1   # نحتاج مجموعًا أكبر
        else:
            right -= 1  # نحتاج مجموعًا أصغر
    return False

sorted_arr = [1, 2, 4, 7, 11, 15]
print(has_pair_with_sum(sorted_arr, 15))  # True (4 + 11)
